class Animal:
    def __init__(self, name):
        self.name = name
    def describe(self):
        return f"{self.name} is an animal"

class Cat(Animal):
    pass

print(Cat("Tom").describe())  # Tom is an animal
Cat has no body of its own, yet its objects have name and describe() from Animal.

class Dog(Animal):
    def fetch(self):
        return f"{self.name} fetches"

print(Dog("Rex").fetch())   # Rex fetches
Animal("x").fetch()  # AttributeError: 'Animal' object has no attribute 'fetch'
Inheritance goes one way: the parent does not get the child's methods.

# Before: Car and Bike both define the same describe()
class Vehicle:
    def __init__(self, wheels):
        self.wheels = wheels
    def describe(self):
        return f"{self.wheels} wheels"

class Car(Vehicle): pass
class Bike(Vehicle): pass
One copy of describe() to read, test and fix.

class Animal:
    def speak(self):
        return "..."

class Dog(Animal):
    def speak(self):
        return "Woof"

print(Dog().speak(), Animal().speak())   # Woof ...

class Base:
    def greet(self):
        return "hi"

class Loud(Base):
    def greet(self):
        return super().greet().upper() + "!"

print(Loud().greet())   # HI!
super().greet() runs the parent's version, and the child adds to its result.

class Loud(Base):
    def greet(self):
        return self.greet().upper()   # calls itself forever
# RecursionError: maximum recursion depth exceeded

class Quiet(Base):
    def greet(self):
        super().greet().lower()       # no return
print(Quiet().greet())   # None

class Animal:
    def __init__(self, name):
        self.name = name

class Cat(Animal):
    pass

Cat("Tom").name   # 'Tom'
Cat()  # TypeError: Animal.__init__() missing 1 required positional argument: 'name'

class Student:
    def __init__(self, name):
        self.name = name

class Grad(Student):
    def __init__(self, name, thesis):
        self.thesis = thesis

Grad("Ana", "Graphs").name
# AttributeError: 'Grad' object has no attribute 'name'
__init__ is overridden like any method, so Student's never ran.

class Grad(Student):
    def __init__(self, name, thesis):
        Student.__init__(self, name)   # same effect here
        self.thesis = thesis
You will see this in older code; it needs self passed explicitly. Prefer super().

class Account:
    def __init__(self, balance):
        self.__balance = balance
class Savings(Account):
    def show(self):
        return self.__balance

Savings(5).show()
# AttributeError: 'Savings' object has no attribute '_Savings__balance'
Two underscores rename the attribute per class; one underscore (_balance) means 'internal, but subclasses may use it'.

class InsufficientFunds(Exception):
    def __init__(self, needed):
        super().__init__(f"need {needed} more")
        self.needed = needed

try:
    raise InsufficientFunds(30)
except InsufficientFunds as e:
    print(e, e.needed)   # need 30 more 30

try:
    raise InsufficientFunds(5)
except Exception:
    print("general")
except InsufficientFunds:
    print("specific")   # never reached
# general
The first matching except wins, so put subclasses first.

class Swimmer:
    def move(self): return "swim"
class Flyer:
    def move(self): return "fly"
class Duck(Swimmer, Flyer):
    pass

print(Duck().move())   # swim

class GreetMixin:
    def greet(self):
        return f"Hi, I'm {self.name}"

class Person(GreetMixin):
    def __init__(self, name):
        self.name = name

print(Person("Ana").greet())   # Hi, I'm Ana
A mixin has no __init__ of its own; it relies on attributes the host class sets.

class Base:
    def hello(self): print("Base")
class L(Base):
    def hello(self): print("L"); super().hello()
class R(Base):
    def hello(self): print("R"); super().hello()
class D(L, R):
    def hello(self): print("D"); super().hello()
D().hello()   # D L R Base (one per line)

class Shape:
    def area(self): return 0
class Square(Shape):
    def __init__(self, side): self.side = side
    def area(self): return self.side ** 2
class Circle(Shape):
    def __init__(self, r): self.r = r
    def area(self): return round(3.14 * self.r ** 2, 2)

for s in [Square(2), Circle(1)]:
    print(s.area())   # 4 then 3.14

# Before
def area(kind, size):
    if kind == "square":
        return size ** 2
    elif kind == "circle":
        return 3.14 * size ** 2
# After: each class knows its own area, so callers just write s.area()

class Report:
    def render(self):
        return self.header() + " | " + self.body()
    def header(self): return "REPORT"
    def body(self): return "(empty)"

class Sales(Report):
    def body(self): return "sales: 42"

print(Sales().render())   # REPORT | sales: 42

class Duck:
    def speak(self): return "Quack"
class Robot:
    def speak(self): return "Beep"

for thing in [Duck(), Robot()]:
    print(thing.speak())   # Quack then Beep
Python only checks that the method exists when it is called.

class Talker:
    def speak(self): print("hello")   # prints, returns None

for t in [Duck(), Talker()]:
    print("says:", t.speak())
# says: Quack / hello / says: None
Interchangeable objects must agree on arguments and return values, not just the name.

class Engine:
    def start(self): return "vroom"

class Car:
    def __init__(self):
        self.engine = Engine()

car = Car()
print(car.engine.start())   # vroom
Read car.engine.start() left to right: the car's engine, then its start method.

