class Car:
    def __init__(self):
        self.engine = Engine()
    def start(self):
        return self.engine.start()

print(Car().start())   # vroom
Callers ask the car; only the car needs to know it has an engine.

class Car:
    def __init__(self):
        self.engine = Engine()      # each car gets its own

class Car2:
    def __init__(self, engine):
        self.engine = engine        # the caller decides; it may be shared
Receiving parts lets you pass in a different (or test) part.

class Stack:
    def __init__(self):
        self._items = []
    def push(self, x):
        self._items.append(x)
    def pop(self):
        return self._items.pop()

Stack().insert(0, 99)
# AttributeError: 'Stack' object has no attribute 'insert'
Only the methods you write are offered.

class Shape:
    def area(self):
        raise NotImplementedError("subclasses must define area")

class Blob(Shape):
    pass

b = Blob()      # created without complaint
b.area()        # NotImplementedError: subclasses must define area
The mistake shows up only when the method is called.

from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self): ...

Shape()
# TypeError: Can't instantiate abstract class Shape without an implementation for abstract method 'area'

class Shape(ABC):
    @abstractmethod
    def area(self): ...
    def describe(self):
        return f"area {self.area()}"

class Sq(Shape):
    def __init__(self, s): self.s = s
    def area(self): return self.s ** 2

print(Sq(3).describe())   # area 9

def notify(sender, text):
    sender.send(text)
    return sender.sent_count()
# notify needs any object with send(text) and sent_count() -> int

class FakeSender:
    def __init__(self): self.messages = []
    def send(self, text): self.messages.append(text)
    def sent_count(self): return len(self.messages)

fake = FakeSender()
assert notify(fake, "hi") == 1 and fake.messages == ["hi"]
Nothing is really sent, yet notify is fully checked.

from abc import ABC, abstractmethod

class Sender(ABC):
    @abstractmethod
    def send(self, text): ...
    @abstractmethod
    def sent_count(self): ...

class EmailSender(Sender): ...   # now must define both

from typing import Protocol

class Speaker(Protocol):
    def speak(self) -> str: ...

def greet(s: Speaker) -> None:
    print(s.speak())
The body ... means 'no code here: just the shape of the method'.

class Dog:
    def speak(self) -> str:
        return "Woof"
class Rock:
    pass

greet(Dog())    # fine: Dog has speak
greet(Rock())
# mypy: error: Argument 1 to "greet" has incompatible type "Rock"; expected "Speaker"

class Circle:
    def __init__(self, radius):
        self.radius = radius
class Rect:
    def __init__(self, w, h):
        self.w = w
        self.h = h

Shape = Circle | Rect
A Shape is either a Circle (with a radius) or a Rect (with w and h), never both.

def area(s: Shape) -> float:
    if isinstance(s, Circle):
        return 3 * s.radius ** 2
    return s.w * s.h

print(area(Circle(2)), area(Rect(2, 5)))   # 12 10

class Ok:
    def __init__(self, value): self.value = value
class Err:
    def __init__(self, message): self.message = message

def parse_age(text: str) -> Ok | Err:
    if not text.isdigit():
        return Err(f"not a number: {text}")
    return Ok(int(text))
Unlike returning None, an Err says what went wrong.

