    def __init__(self, title):
        self.title = title
        self.checked_out = False
    def check_out(self):
        pass   # fill in later
A skeleton fixes names and responsibilities; bodies come next.

account = {"owner": "Ana", "balance": 0}

def deposit(acct, amount):
    acct["balance"] += amount

deposit(account, 50)
print(account["balance"])   # 50
The same dict travels into every function: a class is waiting to be made.

class Account:
    def __init__(self, owner):
        self.owner = owner
        self.balance = 0
    def deposit(self, amount):
        self.balance += amount

acct = Account("Ana")
acct.deposit(50)
print(acct.balance)   # 50
The move from records_as_classes, applied to a whole program: each dict key becomes an attribute and every function taking the dict becomes a method.

class LunchCard:
    def __init__(self, balance):
        self.balance = balance
    def pay(self, price):
        if self.balance < price:
            return False
        self.balance -= price
        return True

card = LunchCard(5)
print(card.pay(3), card.pay(3), card.balance)   # True False 2

class QuizBrain:
    def __init__(self, questions):
        self.questions = questions
        self.score = 0
    def check(self, question, reply):
        if reply == question.answer:
            self.score += 1
        return reply == question.answer
# input() and print() stay in the main loop that uses QuizBrain

def calc(x):
    return x * 1.2
# becomes
VAT_RATE = 0.2
def price_with_vat(net):
    return net * (1 + VAT_RATE)

def ship(order_id, paid):
    if order_id is None:
        return "no order"
    if not paid:
        return "unpaid"
    return "shipped"
Guard clauses handle the special cases first, so the main path is not buried in ifs.

